module fixed_point_adder(
    parameter Q, N, 
    input [N-1:0] a, b,
    output [N-1:0] c
);
// Internal registers for storing the results
reg signed [N-1:0] res;
// Sequential logic block triggered by changes in input signals 'a' or 'b'
always @(a, b) begin
    // Check if the two input numbers have the same sign (both positive or both negative)
    if (a[N-1] == b[N-1])
        res = {a[N-1], (a[N-2:0] + b[N-2:0])}; // Add the two numbers without considering the sign
    // If the two input numbers have different signs
    else if (a[N-1] != b[N-1]) begin
        // If 'a' is greater than 'b', subtract 'b' from 'a'
        if (a > b) begin
            res = {a[N-1], (a[N-2:0] - b[N-2:0])}; // Store the result with the sign of 'a'
        end
        // If 'b' is greater than 'a', subtract 'a' from 'b'
        else if (a < b) begin
            res = {b[N-1], (b[N-2:0] - a[N-2:0])}; // Store the result with the sign of 'b'
            res[N-2] = 1'b0;                       // Set the second-to-last bit to 0 because the result is non-negative
        end
        // If 'a' is equal to 'b', the result will be 0
        else begin
            res = {(N){1'b0}};                     // Store 0 in the result register
        end
    end

    // Display the calculated result
    $display("res=%d\n", res);
end
// Assign the final result to output port 'c'
assign c = res;
endmodule
